"""AES-GCM solver using the lower-level streaming cipher API.

This avoids the extra combined ciphertext/tag allocation made by AESGCM.encrypt.
"""
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

class Solver:
    def solve(self, problem, **kwargs):
        encryptor = Cipher(
            algorithms.AES(problem["key"]),
            modes.GCM(problem["nonce"]),
        ).encryptor()
        aad = problem["associated_data"]
        if aad:
            encryptor.authenticate_additional_data(aad)
        ciphertext = encryptor.update(problem["plaintext"])
        tail = encryptor.finalize()
        if tail:
            ciphertext += tail
        return {"ciphertext": ciphertext, "tag": encryptor.tag}

